INSERT INTO `email_templates` (`email_id`, `email_name`, `email_type`, `email_subject`, `email_body`, `date_created`, `triggers`, `website`, `email_from`, `priority`, `signature`, `category_id`, `notemplate`, `content_type`, `revision_timestamp`, `unsubscribe_link`) VALUES
(1, 'send_refferal', '', 'Invitation - BD Growth suite', '<p>Hi %friend_name%,</p><p>You&#39;re invited to the BD Growth suite, your referral code is <code>%refferal_code%</code>, to join click the link bellow</p><p><a href=\"https://bdgrowthsuite.com/checkout/3?ref=ref\">https://bdgrowthsuite.com/checkout/3?ref=%refferal_code%&nbsp;</a></p>', '', '', 0, '', 0, 0, 0, 0, '', '2020-11-02 11:50:56', 1),
(2, 'registration', '', 'Thank you for signing up with BD Growth Suite.', '<p dir=\"ltr\" style=\"line-height:1.3800000000000001;text-align: justify;margin-top:0pt;margin-bottom:8pt;\"><span style=\"font-size:12pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Hello&nbsp;</span><span style=\"font-family: Calibri, sans-serif; font-size: 16px;\"><strong>%First_name%</strong></span><span style=\"font-family:Calibri,sans-serif;font-size: 18px;\">,&nbsp;</span></p><p dir=\"ltr\" style=\"line-height:1.3800000000000001;text-align: justify;margin-top:0pt;margin-bottom:8pt;\"><span style=\"font-size:12pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Thank you for signing up with BD Growth Suite. You just partnered with the largest in-house Brilliant Directories developer team to work on your business directory/membership website.</span></p><p dir=\"ltr\" style=\"line-height:1.3800000000000001;text-align: justify;margin-top:0pt;margin-bottom:8pt;\"><span style=\"font-size:12pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">We offer nothing but excellence and utmost professionalism. Hop over to our website (</span><a href=\"https://bdgrowthsuite.com/\" style=\"text-decoration: none; display: inline-block; word-break: keep-all;\"><span style=\"font-size:12pt;font-family:Calibri,sans-serif;color:#0563c1;background-color:transparent;font-weight:400;font-style:normal;text-decoration:underline;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">https://bdgrowthsuite.com/</span></a><span style=\"font-size:12pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">) and explore the extensive range of services we have for you. And do not forget to claim and use your FREE $100 credit that we will shortly place in your <strong><a href=\"https://bdgrowthsuite.com/account/wallet\" style=\"display: inline-block; word-break: keep-all;\">BD Wallet</a>.</strong></span></p><p><br></p><p dir=\"ltr\" style=\"line-height:1.3800000000000001;text-align: justify;margin-top:0pt;margin-bottom:8pt;\"><strong><span style=\"font-size:12pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">We are excited to have you onboard with us.</span></strong></p><p><strong><br></strong></p><p><strong><span style=\"font-size: 18px; padding: 15px 0px; font-family: arial; color: #0d83dd;\">Your Log In Details</span>:</strong></p><table border=\"0\" cellpadding=\"6\" cellspacing=\"6\" style=\"font-weight: bold; background: rgb(227, 227, 227); width: 100%; border-collapse: separate; table-layout: auto;\"><tbody><tr><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\">Username:</span></td><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\">%user_email%</span></td></tr><tr><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\">Password:</span></td><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\">(Entered During Signup)</span></td></tr></tbody></table><p><strong>You can <a href=\"https://bdgrowthsuite.com/login/retrieval\" style=\"display: inline-block; word-break: keep-all;\">click here</a> to reset your password in case you forgot your password.</strong></p><p><strong><br></strong></p><p dir=\"ltr\" style=\"line-height:1.3800000000000001;text-align: justify;margin-top:0pt;margin-bottom:8pt;\"><strong><span style=\"font-size:12pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Regards,</span></strong></p><p dir=\"ltr\" style=\"line-height:1.3800000000000001;text-align: justify;margin-top:0pt;margin-bottom:8pt;\"><strong><span style=\"font-size:12pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">The BD Growth Suite Team.</span></strong></p><p><br></p>', '', '', 0, '', 0, 0, 0, 0, '', '2025-12-15 09:39:46', 1),
