(8, 'welcome-basic', '', '[Action Required]  Please verify your email - %%%website_name%%%', '<p><span style=\"font-size: 22px; padding: 15px 0px; font-weight: normal; font-family: arial; color: #0d83dd;\">Thank You For Partnering with %%%website_name%%%!</span></p><p><span style=\"font-size: 14px;\"><br>Please verify your email address so that we can send you the updates through email notifications&nbsp;for your purchase and inquiries you submit, and activate your account.</span><span style=\"font-size: 14px;\">&nbsp;</span></p><p><span style=\"font-size: 14px;\">Please click on the link below to activate your account.</span><br><br><a href=\"%confirm_link%\" style=\"font-weight: bold; font-size: 15px;\">%confirm_link%</a><br><br><br><span style=\"font-size: 18px; padding: 15px 0px; font-weight: normal; font-family: arial; color: #0d83dd;\"><strong>Your Login Details</strong></span><strong>:</strong></p><table border=\"0\" cellpadding=\"6\" cellspacing=\"6\" style=\"font-weight: bold; background: #e8f1fa;\"><tbody><tr><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\">Username:</span></td><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\">%%%email%%%</span></td></tr><tr><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\">Password:</span></td><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\">(Entered During Signup)</span></td></tr></tbody></table><p><br><br><span style=\"font-size: 14px;\">If you need any assistance while using our website,</span> <span style=\"font-size: 14px;\">please reply directly to this email.</span></p><p><br></p><p><span style=\"font-size: 14px;\">Thank you,&nbsp;</span></p><p><span style=\"font-size: 14px;\">The %%%website_name%%% Team.</span></p>', '', '', 0, '', 0, 0, 1, 0, '', '2023-04-28 13:35:16', 1),
(9, 'maintenance-message', '', 'Thank you for inquiring about our Maintenance Service', '<p dir=\"ltr\" style=\"line-height:1.3800000000000001;text-align: justify;margin-top:0pt;margin-bottom:8pt;\"><span style=\"font-size:16pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:700;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Thank You for Choosing BD Growth Suite</span></p><p dir=\"ltr\" style=\"line-height:1.3800000000000001;text-align: justify;margin-top:0pt;margin-bottom:8pt;\"><br></p><p dir=\"ltr\" style=\"line-height:1.3800000000000001;text-align: justify;margin-top:0pt;margin-bottom:8pt;\"><span style=\"font-size:12pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">Hello&nbsp;</span><strong><span style=\"font-size: 18px;\">%First_name%, &nbsp;</span></strong></p><p dir=\"ltr\" style=\"line-height:1.3800000000000001;text-align: justify;margin-top:0pt;margin-bottom:8pt;\"><span style=\"font-size:12pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">We have received your message&nbsp;for maintaining your Brilliant Directories Website. We will mobilize our expert team soon and get in touch with you with the details and further steps.</span></p><p dir=\"ltr\" style=\"line-height:1.3800000000000001;text-align: justify;margin-top:0pt;margin-bottom:8pt;\"><span style=\"font-size:12pt;font-family:Calibri,sans-serif;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\">We are excited to have you onboard BD Gr