(30, 'marketingemail_template', '', 'marketingemail_template', '<div style=\"background-color: #111d49;\"><div style=\"text-align: center;\"><img src=\"https://bdgrowthsuite.com/images/3d4e26b8110c94208c3099519b16b288d4d582d9.png\" style=\"width: 300px; height: auto; max-width: 100%;\" class=\"fr-dib\" width=\"302\"></div><div>&nbsp;</div><h1 style=\"text-align: center;\">&nbsp;<strong><span style=\"font-size: 36px; color: rgb(255, 255, 255);\">WELCOME</span></strong></h1><p><br></p><h4 style=\"text-align: center;\"><strong><span style=\"color: rgb(255, 255, 255);\">Confirm your signup and get</span></strong></h4><h2 style=\"text-align: center;\"><strong><span style=\"color: rgb(246, 208, 159);\">20% Promo code</span></strong></h2><p><br></p><p style=\"text-align: center;\"><a href=\"\"><strong><span style=\"font-size: 18px; background-color: rgb(246, 208, 159); color: rgb(255, 255, 255); padding: 10px 40px; border-radius: 5px;\">CONFIRM</span></strong></a></p><p style=\"text-align: center; line-height: 1;\"><br></p><p style=\"text-align: center; line-height: 1;\"><span style=\"color: rgb(255, 255, 255);\">Hi Firstname</span></p><div class=\"fabric-editor-block-mark fabric-editor-align-center\" data-align=\"center\" data-pm-slice=\"1 1 []\" id=\"isPasted\"><p style=\"text-align: center;\"><span style=\"color: #B6B8D1;\" class=\"text-color\"><span style=\"font-size: 16px;\"><span style=\"font-family: Lato, Arial, sans-serif; color: rgb(255, 255, 255);\"><span style=\"background-color: transparent;\">Use this space to welcome your new contact to your list and confirm their signup. You should also provide anything that you promisedon the signup page</span></span></span></span></p><div class=\"fabric-editor-block-mark fabric-editor-align-center\" data-align=\"center\" data-pm-slice=\"1 1 []\" id=\"isPasted\"><p style=\"text-align: center;\"><span style=\"color: rgb(255, 255, 255);\" class=\"text-color\"><span style=\"font-size: 18px;\"><span style=\"font-family: Lato, Arial, sans-serif;\">If you promised some tips or information,&nbsp;</span></span></span><span style=\"color: rgb(255, 255, 255);\"><br></span><span style=\"color: rgb(255, 255, 255);\" class=\"text-color\"><span style=\"font-size: 18px;\"><span style=\"font-family: Lato, Arial, sans-serif;\">you could provide them here:</span></span></span></p></div><div><span style=\"color: rgb(255, 255, 255);\">&nbsp;</span></div><table cellpadding=\"15\" style=\"width: 100%;\"><tbody><tr><td style=\"width: 33.3333%; text-align: center; vertical-align: top;\"><p><span class=\"fr-img-caption fr-dib\" style=\"width: 60px;\"><span class=\"fr-img-wrap\"><img src=\"https://bdgrowthsuite.com/images/204e91c80dda690f7ec13ecf22b7714cb3a38f1f.png\" style=\"width: 60px; max-width: 100%; height: auto;\" class=\"fr-dib\" width=\"62\"></span> <br><span style=\"font-size: 18px; color: rgb(255, 255, 255);\">Information1</span></span></p></td><td style=\"width: 33.3333%; text-align: center; vertical-align: top;\"><p><span style=\"color: rgb(255, 255, 255);\"><img src=\"https://bdgrowthsuite.com/images/410bc29fbf824d0475fa7ef611c1146ecc209bb3.png\" style=\"width: 60px; max-width: 100%; height: auto;\" class=\"fr-dib\" width=\"62\"></span><br><span style=\"font-size: 18px; color: rgb(255, 255, 255);\">Informatiom2</span></p></td><td style=\"width: 33.3333%; text-align: center; vertical-align: top;\"><p><span style=\"color: rgb(255, 255, 255);\"><img src=\"https://bdgrowthsuite.com/images/157ca47a5e4a93fd9753383fae7ff8d9693eaf47.png\" style=\"width: 60px; max-width: 100%; height: auto;\" class=\"fr-dib\" width=\"62\"></span><br><span style=\"font-size: 18px; color: rgb(255, 255, 255);\">Infirmation3</span></p></td></tr></tbody></table><div><span style=\"color: rgb(255, 255, 255);\">&nbsp;</span></div><p data-pm-slice=\"1 1 []\" id=\"isPasted\" style=\"text-align: center; padding: 0px 14px;\"><span style=\"color: rgb(255, 255, 255);\" class=\"text-color\"><span style=\"font-size: 16px;\"><span style=\"font-family: Lato, Arial, sans-serif;\">You can now introduce any products or services that you want to promote, or what action they should take next.</span></span></span></p><p data-pm-slice=\"1 1 []\" id=\"isPasted\" style=\"text-align: center; padding: 0px 14px;\"><span style=\"color: rgb(255, 255, 255);\" class=\"text-color\"><span style=\"font-size: 14px;\"><span style=\"font-family: Lato, Arial, sans-serif;\">P.S. Sometimes including a &ldquo;P.S.&rdquo; grabs attention and you can ask them to perform an action like following you on social media, or browsing your website.</span></span></span></p><p data-pm-slice=\"1 1 []\" style=\"text-align: center;\"><br></p></div></div>', '', '', 0, '', 0, 0, 0, 0, '', '2023-03-29 06:11:01', 1),
