(35, 'hire-developers-admin', '', 'Admin - Thank You for Your Inquiry!', '<p id=\"isPasted\">TO ADMIN:<br><span style=\"background-color: transparent;\">Copy of email that the client received:</span></p><p id=\"isPasted\">Hi %%%First_name%%%,</p><p>Thank you for reaching out! We&rsquo;ve received your inquiry and our team is reviewing your specifications. Here&rsquo;s a summary of what you submitted:</p><p><br></p><p><strong><span style=\"font-size: 18px; padding: 15px 0px; font-family: arial; color: #0d83dd;\">Your Submission:</span></strong></p><table border=\"0\" cellpadding=\"6\" cellspacing=\"6\" style=\"font-weight: bold; background: rgb(227, 227, 227); width: 100%; border-collapse: separate; table-layout: auto;\" class=\"froala-table\"><tbody><tr><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\">Name:</span></td><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\">%First_name%</span></td></tr><tr><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\">Email:</span></td><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\">%%%user_email%%%</span></td></tr><tr><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\">Phone Number:</span></td><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\">%%%phone_number%%%</span></td></tr><tr><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\" id=\"isPasted\">Company:</span><br></td><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\" id=\"isPasted\">%%%company%%%</span><br></td></tr><tr><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\" id=\"isPasted\">Short Title:</span><br></td><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\" id=\"isPasted\">%%%short_title%%%</span><br></td></tr><tr><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\" id=\"isPasted\">Extra Notes:</span><br></td><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\" id=\"isPasted\">%%%extra_notes%%%</span><br></td></tr><tr><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\" id=\"isPasted\">Specification:</span><br></td><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\" id=\"isPasted\">%%%specification%%%</span><br></td></tr><tr><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\" id=\"isPasted\">File:</span><br></td><td style=\"background: #ffffff;\"><span style=\"font-size: 14px;\" id=\"isPasted\">%%%file_name%%%</span><br></td></tr></tbody></table><p><br></p><p id=\"isPasted\">We&rsquo;ll get back to you soon with technical feedback and next steps.</p><p>Please check your email for updates, and if you have any questions, feel free to reply directly to this message.</p><p>Best regards,</p><p><span style=\"font-size: 12px; font-family: Arial; color: rgb(0, 0, 0); background-color: transparent; font-weight: 400; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap;\">The BD Growth Suite Team.</span></p>', '', '', 0, '', 0, 0, 0, 0, '', '2025-01-28 10:41:25', 1),
